### app/style.css (10576 bytes)

```css
/* HearthLedger — a warm paper-and-ink look: cream background, deep green and
   terracotta accents, rounded cards, system fonts only (the site must run
   offline, so nothing is fetched). Layout is fluid: panels sit two-up on a
   desktop and stack on a phone, and the nav wraps under the brand. */

:root {
  --ink: #26332b;
  --muted: #68766c;
  --paper: #faf6ee;
  --card: #ffffff;
  --line: #e5dcc8;
  --green: #2e7d5b;
  --green-dark: #1f5c40;
  --terra: #e07840;
  --gold: #c9a227;
  --red: #b3402e;
  --radius: 14px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: "Segoe UI", system-ui, -apple-system, "Helvetica Neue", Arial, sans-serif;
  line-height: 1.5;
}

a { color: var(--green-dark); }

/* --- header ------------------------------------------------------------ */

.site-head {
  display: flex; flex-wrap: wrap; align-items: center; gap: 0.4rem 1.2rem;
  padding: 0.9rem 1.4rem;
  background: var(--green-dark);
  color: #fff;
  position: sticky; top: 0; z-index: 5;
}
.brand { color: #fff; font-weight: 800; font-size: 1.3rem; text-decoration: none; letter-spacing: 0.2px; }
.site-head nav { display: flex; flex-wrap: wrap; gap: 0.2rem 0.4rem; margin-left: auto; }
.site-head nav a {
  color: #dcebe2; text-decoration: none; padding: 0.32rem 0.7rem; border-radius: 999px; font-size: 0.95rem;
}
.site-head nav a:hover { background: rgba(255,255,255,0.14); color: #fff; }
.site-head nav a.active { background: #fff; color: var(--green-dark); font-weight: 700; }

main { max-width: 1080px; margin: 0 auto; padding: 1.4rem 1.2rem 2.5rem; }

/* --- hero & cards ------------------------------------------------------- */

.hero h1 { font-size: 2rem; margin: 0.2rem 0 0.4rem; }
.lede { color: var(--muted); max-width: 62ch; margin: 0 0 1.1rem; font-size: 1.05rem; }

.cards { display: grid; grid-template-columns: repeat(4, 1fr); gap: 0.9rem; margin: 1rem 0; }
.cards.two { grid-template-columns: repeat(2, 1fr); }
.card {
  background: var(--card); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 1rem 1.1rem; box-shadow: 0 1px 3px rgba(38, 51, 43, 0.06);
}
.card h2 { margin: 0; font-size: 0.85rem; text-transform: uppercase; letter-spacing: 0.08em; color: var(--muted); }
.card .big { font-size: 1.7rem; font-weight: 800; margin: 0.25rem 0 0.1rem; }
.card .sub { margin: 0; color: var(--muted); font-size: 0.9rem; }
.card.accent { border-top: 4px solid var(--terra); }
.card:not(.accent) { border-top: 4px solid var(--green); }

.alert {
  background: #fdeee7; border: 1px solid #f2c4ae; color: #7c3a1e;
  border-radius: var(--radius); padding: 0.7rem 1rem;
}

/* --- panels & grids ----------------------------------------------------- */

.panel {
  background: var(--card); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 1.1rem 1.3rem; margin: 1rem 0; box-shadow: 0 1px 3px rgba(38, 51, 43, 0.05);
}
.panel h2 { margin-top: 0.2rem; }
.grid-two { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; }
.grid-two .panel { margin: 0; }
.grid-two { margin: 1rem 0; }
.more { margin-bottom: 0.2rem; }
.note { color: var(--muted); font-size: 0.94rem; }
.subhead { margin: 1rem 0 0.3rem; font-size: 1rem; }

/* --- lists -------------------------------------------------------------- */

.rows { list-style: none; margin: 0; padding: 0; }
.rows li {
  display: flex; align-items: baseline; gap: 0.7rem;
  padding: 0.45rem 0; border-bottom: 1px dashed var(--line);
}
.rows li:last-child { border-bottom: none; }
.rows li b { margin-left: auto; white-space: nowrap; }
.rows li em { color: var(--muted); font-style: normal; font-size: 0.88rem; white-space: nowrap; }
.rows li span:first-child { color: var(--muted); }

.goal-mini { list-style: none; margin: 0; padding: 0; }
.goal-mini li { display: flex; align-items: center; gap: 0.7rem; padding: 0.4rem 0; border-bottom: 1px dashed var(--line); }
.goal-mini li:last-child { border-bottom: none; }
.goal-mini .bar-track { flex: 1; }
.goal-mini b { min-width: 3ch; text-align: right; }

/* --- charts ------------------------------------------------------------- */

.donut-wrap { display: flex; gap: 1.2rem; align-items: center; flex-wrap: wrap; }
.donut { width: 190px; height: 190px; flex: none; }
.donut-total { font-size: 1.45rem; font-weight: 800; fill: var(--ink); }
.donut-label { font-size: 0.8rem; fill: var(--muted); text-transform: uppercase; letter-spacing: 0.08em; }
.legend { list-style: none; margin: 0; padding: 0; flex: 1; min-width: 190px; }
.legend li { display: flex; align-items: center; gap: 0.5rem; padding: 0.22rem 0; }
.legend li b { margin-left: auto; }
.dot { width: 12px; height: 12px; border-radius: 4px; flex: none; }

.bars { width: 100%; height: auto; }
.bar-value { font-size: 0.72rem; font-weight: 700; fill: var(--ink); }
.bar-label { font-size: 0.72rem; fill: var(--muted); }

.bar-track { background: #efe9da; border-radius: 999px; height: 10px; overflow: hidden; }
.bar-fill { background: var(--green); height: 100%; border-radius: 999px; }
