  <section class="grid-two">
    <article class="panel">
      <h2>Still to pay — ${money(dueTotal)}</h2>
      <ul class="rows bills">${dueList || '<li>Nothing outstanding. 🎉</li>'}</ul>
      <p class="more"><a href="#/bills">Open bills &amp; reminders →</a></p>
